INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'heritage', 'n.', '/ˈherɪtɪdʒ/', '遗产(尤指国家或社会长期形成的历史、传统和特色)', 'We must protect our cultural heritage for future generations.', '我们必须为子孙后代保护我们的文化遗产。', 'Cultural Heritage', 1, 0, 'senior', 'wordlist', 'required2', 'U1', 'cultural heritage', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'relic', 'n.', '/ˈrelɪk/', '遗物;遗迹;遗存', 'The dam would have destroyed many ancient cultural relics.', '这座大坝本会毁掉许多古老的文物遗迹。', 'Cultural Heritage', 2, 0, 'senior', 'wordlist', 'required2', 'U1', 'cultural relics', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'preserve', 'vt./n.', '/prɪˈzɜːv/', '保存;保护;维持;保护区', 'Workers tried hard to preserve the temple from the rising water.', '工人们努力保护这座庙宇免遭上涨的水淹没。', 'Cultural Heritage', 3, 0, 'senior', 'wordlist', 'required2', 'U1', 'preserve the temple', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'dam', 'n.', '/dæm/', '水坝;拦河坝', 'The government planned to build a dam across the Nile.', '政府计划在尼罗河上修建一座大坝。', 'Cultural Heritage', 4, 0, 'senior', 'wordlist', 'required2', 'U1', 'build a dam', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'temple', 'n.', '/ˈtempl/', '庙;寺;神殿', 'Engineers moved the ancient temple piece by piece to a safe place.', '工程师们把这座古庙一块一块地搬到了安全的地方。', 'Cultural Heritage', 5, 0, 'senior', 'wordlist', 'required2', 'U1', 'an ancient temple', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'quote', 'vt.', '/kwəʊt/', '引用;引述', 'The reporter quoted a famous saying about cultural heritage.', '记者引用了一句关于文化遗产的名言。', 'Cultural Heritage', 6, 0, 'senior', 'wordlist', 'required2', 'U1', 'quote a saying', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'committee', 'n.', '/kəˈmɪti/', '委员会', 'A committee was established to limit damage to the buildings.', '成立了一个委员会以减少对这些建筑的损害。', 'Cultural Heritage', 7, 0, 'senior', 'wordlist', 'required2', 'U1', 'set up a committee', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'establish', 'vt.', '/ɪˈstæblɪʃ/', '建立;创立;设立', 'They decided to establish a fund to save the temples.', '他们决定设立一笔基金来拯救这些庙宇。', 'Cultural Heritage', 8, 0, 'senior', 'wordlist', 'required2', 'U1', 'establish a committee', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'fund', 'n.', '/fʌnd/', '基金;专款;资金', 'The group raised funds within the international community.', '该团体在国际社会中筹集了资金。', 'Cultural Heritage', 9, 0, 'senior', 'wordlist', 'required2', 'U1', 'raise funds', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'contribute', 'vi./vt.', '/kənˈtrɪbjuːt/', '捐献;捐助;贡献', 'Fifty countries contributed money to the Aswan Dam project.', '五十个国家为阿斯旺大坝项目捐了款。', 'Cultural Heritage', 10, 0, 'senior', 'wordlist', 'required2', 'U1', 'contribute to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'contribution', 'n.', '/ˌkɒntrɪˈbjuːʃn/', '捐款;贡献;捐赠', 'Every country made a contribution to rescue the cultural sites.', '每个国家都为拯救这些文化遗址作出了贡献。', 'Cultural Heritage', 11, 0, 'senior', 'wordlist', 'required2', 'U1', 'make a contribution', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'donate', 'vt.', '/dəʊˈneɪt/', '捐赠;赠送;捐(血)', 'Many nations donated millions of dollars to the project.', '许多国家为该项目捐赠了数百万美元。', 'Cultural Heritage', 12, 0, 'senior', 'wordlist', 'required2', 'U1', 'donate money to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'investigate', 'vi./vt.', '/ɪnˈvestɪɡeɪt/', '调查;研究', 'Experts were asked to investigate the issue carefully.', '专家受邀仔细调查这个问题。', 'Cultural Heritage', 13, 0, 'senior', 'wordlist', 'required2', 'U1', 'investigate the issue', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'conduct', 'vt./n.', '/kənˈdʌkt/', '组织;安排;进行;管理;行为;举止', 'The team conducted several tests before making a proposal.', '团队在提出方案之前进行了几次测试。', 'Cultural Heritage', 14, 0, 'senior', 'wordlist', 'required2', 'U1', 'conduct tests', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'proposal', 'n.', '/prəˈpəʊzl/', '提议;建议;方案', 'They made a proposal for how the buildings could be saved.', '他们就如何拯救这些建筑提出了一个方案。', 'Cultural Heritage', 15, 0, 'senior', 'wordlist', 'required2', 'U1', 'make a proposal', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'document', 'n./vt.', '/ˈdɒkjumənt/', '文件;公文;文档;记录;记载', 'Finally, a document was signed and the work began.', '最后,一份文件被签署,工程随之开始。', 'Cultural Heritage', 16, 0, 'senior', 'wordlist', 'required2', 'U1', 'sign a document', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'limit', 'n./vt.', '/ˈlɪmɪt/', '限度;限制;限定', 'The committee tried to limit the damage to the temples.', '委员会努力把对庙宇的损害降到最低。', 'Cultural Heritage', 17, 0, 'senior', 'wordlist', 'required2', 'U1', 'limit the damage', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'prevent', 'vt.', '/prɪˈvent/', '阻止;阻碍;防止', 'The plan aimed to prevent the loss of cultural relics.', '这个方案旨在防止文物的损失。', 'Cultural Heritage', 18, 0, 'senior', 'wordlist', 'required2', 'U1', 'prevent the loss', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'loss', 'n.', '/lɒs/', '丧失;损失;遗失', 'Saving the temples prevented a great loss for human history.', '拯救这些庙宇避免了人类历史上的巨大损失。', 'Cultural Heritage', 19, 0, 'senior', 'wordlist', 'required2', 'U1', 'prevent the loss', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'process', 'n./vt.', '/ˈprəʊses/', '过程;进程;步骤;处理;加工', 'A guide explained the process of building the pyramid.', '一位向导解释了建造金字塔的过程。', 'Cultural Heritage', 20, 0, 'senior', 'wordlist', 'required2', 'U1', 'the building process', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'balance', 'n./vt.', '/ˈbæləns/', '平衡;均衡;使平衡', 'We must keep a balance between progress and protection.', '我们必须在发展与保护之间保持平衡。', 'Cultural Heritage', 21, 0, 'senior', 'wordlist', 'required2', 'U1', 'keep a balance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'promote', 'vt.', '/prəˈməʊt/', '促进;提升;推广;宣传', 'The project hopes to promote interest in China''s history.', '这个项目希望促进人们对中国历史的兴趣。', 'Cultural Heritage', 22, 0, 'senior', 'wordlist', 'required2', 'U1', 'promote culture', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'tradition', 'n.', '/trəˈdɪʃn/', '传统;惯例;传统信仰或风俗', 'Cultural heritage includes a country''s customs and traditions.', '文化遗产包括一个国家的习俗和传统。', 'Cultural Heritage', 23, 0, 'senior', 'wordlist', 'required2', 'U1', 'ancient traditions', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'identify', 'vt.', '/aɪˈdentɪfaɪ/', '确认;认出;识别;找到', 'Scientists worked hard to identify each ancient relic.', '科学家们努力辨认每一件古代文物。', 'Cultural Heritage', 24, 0, 'senior', 'wordlist', 'required2', 'U1', 'identify a relic', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'digital', 'adj.', '/ˈdɪdʒɪtl/', '数码的;数字显示的;数字技术的', 'Researchers collected digital images of the cave paintings.', '研究人员收集了这些洞窟壁画的数字图像。', 'Cultural Heritage', 25, 0, 'senior', 'wordlist', 'required2', 'U1', 'digital images', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'image', 'n.', '/ˈɪmɪdʒ/', '图像;形象;印象', 'Nearly 500,000 high-quality images have been produced.', '已经制作了将近五十万张高质量图像。', 'Cultural Heritage', 26, 0, 'senior', 'wordlist', 'required2', 'U1', 'a clear image', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'cave', 'n.', '/keɪv/', '山洞;洞穴', 'Tourists from all over the world visit the famous caves.', '来自世界各地的游客都来参观这些著名的洞窟。', 'Cultural Heritage', 27, 0, 'senior', 'wordlist', 'required2', 'U1', 'the Mogao Caves', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'historic', 'adj.', '/hɪˈstɒrɪk/', '历史上著名(或重要)的;有史时期的', 'We should safeguard historic relics for future generations.', '我们应当为子孙后代守护历史文物。', 'Cultural Heritage', 28, 0, 'senior', 'wordlist', 'required2', 'U1', 'historic sites', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'quality', 'n./adj.', '/ˈkwɒləti/', '质量;品质;素质;特征;优质的', 'The team takes high-quality photos of the cultural relics.', '团队为这些文物拍摄高质量的照片。', 'Cultural Heritage', 29, 0, 'senior', 'wordlist', 'required2', 'U1', 'high quality', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'attempt', 'n./vt.', '/əˈtempt/', '企图;试图;尝试', 'The government''s first attempt to build the dam led to protests.', '政府修建大坝的最初尝试引发了抗议。', 'Cultural Heritage', 30, 0, 'senior', 'wordlist', 'required2', 'U1', 'make an attempt', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'protest', 'vi./vt.', '/prəˈtest/', '抗议;(公开)反对', 'Many citizens protested against destroying the temples.', '许多市民抗议毁掉这些庙宇。', 'Cultural Heritage', 31, 0, 'senior', 'wordlist', 'required2', 'U1', 'lead to protests', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'issue', 'n./vt.', '/ˈɪʃuː/', '重要议题;争论的问题;宣布;公布', 'Protecting cultural heritage is an important issue today.', '保护文化遗产是当今一个重要的议题。', 'Cultural Heritage', 32, 0, 'senior', 'wordlist', 'required2', 'U1', 'a serious issue', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'opinion', 'n.', '/əˈpɪnjən/', '意见;想法;看法', 'In my opinion, saving the temples was truly worthwhile.', '在我看来,拯救这些庙宇确实是值得的。', 'Cultural Heritage', 33, 0, 'senior', 'wordlist', 'required2', 'U1', 'in my opinion', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'worthwhile', 'adj.', '/ˌwɜːθˈwaɪl/', '值得做的;值得花时间的', 'Spending so much money on the temples was worthwhile.', '在这些庙宇上花这么多钱是值得的。', 'Cultural Heritage', 34, 0, 'senior', 'wordlist', 'required2', 'U1', 'a worthwhile project', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'department', 'n.', '/dɪˈpɑːtmənt/', '部;司;科;部门', 'The group asked for contributions from different departments.', '该团体向不同部门请求捐助。', 'Cultural Heritage', 35, 0, 'senior', 'wordlist', 'required2', 'U1', 'different departments', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'professional', 'adj./n.', '/prəˈfeʃənl/', '专业的;职业的;专业人员', 'We met a professional guide at the entrance to the pyramid.', '我们在金字塔入口处遇到了一位专业向导。', 'Cultural Heritage', 36, 0, 'senior', 'wordlist', 'required2', 'U1', 'a professional archaeologist', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'entrance', 'n.', '/ˈentrəns/', '入口;进入;入场', 'A crowd of tourists waited at the entrance to the temple.', '一群游客在庙宇的入口处等候。', 'Cultural Heritage', 37, 0, 'senior', 'wordlist', 'required2', 'U1', 'the main entrance', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'exit', 'n./vi.', '/ˈeksɪt/', '出口;通道;出去;离去', 'An exit is the door through which you can leave a building.', '出口就是你可以离开一座建筑的那扇门。', 'Cultural Heritage', 38, 0, 'senior', 'wordlist', 'required2', 'U1', 'the exit door', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'mirror', 'n.', '/ˈmɪrə(r)/', '镜子;反映', 'The guide said the ancient mirror could tell right from wrong.', '向导说这面古镜能分辨是非。', 'Cultural Heritage', 39, 0, 'senior', 'wordlist', 'required2', 'U1', 'an ancient mirror', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'roof', 'n.', '/ruːf/', '顶部;屋顶', 'She looked at a strange carving on the temple roof.', '她看着庙顶上一个奇特的雕刻。', 'Cultural Heritage', 40, 0, 'senior', 'wordlist', 'required2', 'U1', 'a carving on the roof', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'former', 'adj.', '/ˈfɔːmə(r)/', '以前的;(两者中)前者的', 'By studying photos of the former palace, they rebuilt it exactly.', '通过研究旧宫殿的照片,他们将它原样重建。', 'Cultural Heritage', 41, 0, 'senior', 'wordlist', 'required2', 'U1', 'the former palace', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'likely', 'adj./adv.', '/ˈlaɪkli/', '可能的;可能地', 'Water from the dam would likely damage the temples.', '大坝的水很可能损坏这些庙宇。', 'Cultural Heritage', 42, 0, 'senior', 'wordlist', 'required2', 'U1', 'be likely to', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'overseas', 'adj./adv.', '/ˌəʊvəˈsiːz/', '海外的;在海外', 'Some Chinese cultural relics are now kept overseas.', '一些中国文物如今被保存在海外。', 'Cultural Heritage', 43, 0, 'senior', 'wordlist', 'required2', 'U1', 'overseas relics', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'throughout', 'prep.', '/θruːˈaʊt/', '各处;遍及;自始至终', 'The caves were a key stop throughout China''s ancient history.', '这些洞窟在中国古代历史中始终是一个重要驿站。', 'Cultural Heritage', 44, 0, 'senior', 'wordlist', 'required2', 'U1', 'throughout history', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'within', 'prep./adv.', '/wɪˈðɪn/', '在(某段时间、距离或范围)之内', 'The committee raised funds within the international community.', '委员会在国际社会内部筹集了资金。', 'Cultural Heritage', 45, 0, 'senior', 'wordlist', 'required2', 'U1', 'within the community', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'creative', 'adj.', '/kriˈeɪtɪv/', '创造性的;有创造力的;有创意的', 'Students found creative ways to protect their heritage.', '学生们找到了保护遗产的创造性方法。', 'Cultural Heritage', 46, 0, 'senior', 'wordlist', 'required2', 'U1', 'creative ways', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'disappear', 'vi.', '/ˌdɪsəˈpɪə(r)/', '消失;灭绝;消亡', 'UNESCO prevents heritage sites from disappearing forever.', '联合国教科文组织防止遗产地永远消失。', 'Cultural Heritage', 47, 0, 'senior', 'wordlist', 'required2', 'U1', 'disappear forever', NULL);
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip) VALUES (10, 'forever', 'adv.', '/fərˈevə(r)/', '永远;长久地', 'Neither people nor buildings last forever, but photos help us remember them.', '人和建筑都不会永存,但照片能帮我们记住它们。', 'Cultural Heritage', 48, 0, 'senior', 'wordlist', 'required2', 'U1', 'last forever', NULL);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u1.01', '①who / whom(先行词指人)', 'A2', 10, '必修二 U1 — 先行词指人。从句缺主语用 who;从句缺宾语用 whom(尤其介词后、或正式书面)。', 1, 'required2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u1.02', '②which / that(先行词指物)', 'A2', 10, '必修二 U1 — 先行词指物、从句缺主语或宾语,用 which 或 that;that 不能用于介词后,不能引导非限制性从句。', 2, 'required2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth) VALUES ('u1.03', '③介词+which/whom · whose · 关系副词 where/when/why', 'A2', 10, '必修二 U1 — 从句不缺主宾、只缺状语:地点用 where、时间用 when、原因用 why,或用「介词+which/whom」;表所属用 whose。', 3, 'required2', 'U1', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0);
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.01'), 'The archaeologist ____ found the ancient relics became famous all over the world.', 'who', 'which', 'whose', 'where', 'A', '先行词 archaeologist 指人、从句缺主语 → who。', 2, 1, 'mcq');
