INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'There may come a time ____ these old traditions disappear forever.', 'where', 'why', 'when', 'which', 'C', '先行词 time 表时间、从句完整 → when。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'We met the archaeologist ____ knowledge of the pyramid amazed us all.', 'who', 'which', 'where', 'whose', 'D', '表所属(他的知识)→ whose。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'The way in ____ the temples were saved became a model for the world.', 'which', 'where', 'when', 'whose', 'A', '介词 in 后指物 → which(in which)。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'This is the museum ____ ancient bones and relics are carefully kept.', 'which', 'where', 'why', 'whose', 'B', '先行词 museum 表地点、从句完整 → where。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), '1980 was the year ____ the Aswan Dam project was finally completed.', 'where', 'why', 'when', 'which', 'C', '先行词 year 表时间、从句完整 → when。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'He is the engineer ____ team moved twenty-two temples in twenty years.', 'who', 'which', 'where', 'whose', 'D', '表所属(他的团队)→ whose。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'Calligraphy is an art form by ____ the past and present are connected.', 'which', 'where', 'when', 'whose', 'A', '介词 by 后指物 → which(by which)。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'Mount Tai is the mountain ____ thousands of carvings have been studied.', 'which', 'where', 'why', 'whose', 'B', '先行词 mountain 表地点、从句完整 → where。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'I still remember the moment ____ the first temple was lifted into place.', 'where', 'why', 'when', 'which', 'C', '先行词 moment 表时间、从句完整 → when。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'She is the volunteer ____ photos of old buildings are kept in the museum.', 'who', 'which', 'where', 'whose', 'D', '表所属(她的照片)→ whose。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'These are the tools with ____ the workers took the temple apart.', 'which', 'where', 'when', 'whose', 'A', '介词 with 后指物 → which(with which)。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'Egypt is the country ____ the world''s most famous pyramids stand.', 'which', 'where', 'why', 'whose', 'B', '先行词 country 表地点、从句完整 → where。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'That was the year ____ fifty countries donated money to the project.', 'where', 'why', 'when', 'which', 'C', '先行词 year 表时间、从句完整 → when。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE volume='required2' AND unit='U1' AND code='u1.03'), 'Please tell me the reason ____ the old palace was rebuilt so carefully.', 'where', 'when', 'whose', 'why', 'D', '先行词 reason、从句缺原因状语 → why。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Saving the Temples on the Nile', 'In the 1950s, the Egyptian government wanted to build a new dam across the Nile. The dam would control floods, produce electricity, and bring water to more farmers. But the plan led to protests, because the rising water would likely damage many temples and destroy cultural relics. After listening to scientists and to citizens who lived near the river, the government turned to the United Nations for help in 1959. A committee was set up to limit the damage and prevent the loss of the relics. Experts studied the problem and made a proposal. Then, over twenty years, thousands of engineers and workers took the temples down piece by piece and put them back together in a place where the water could not reach them. Fifty countries donated nearly eighty million dollars. When the project ended in 1980, it was seen as a great success and a model of how nations can work together.', 'Cultural Heritage', 154, '[{"q":"Why did the Egyptian government want to build the dam?","answer":"A","options":["To control floods and supply water and electricity.","To attract more tourists to the river.","To destroy the old temples on purpose.","To stop ships from using the Nile."],"explanation":"原文 ''control floods, produce electricity, and bring water'' 的转述。"},{"q":"How were the temples finally saved?","answer":"B","options":["They were left where they were.","They were taken apart and rebuilt on safer ground.","They were covered with water to protect them.","They were sold to other countries."],"explanation":"原文 ''took the temples down piece by piece and put them back together'' 的转述。"},{"q":"What does the text suggest about the project''s result?","answer":"A","options":["It showed that countries can solve problems together.","It failed and was soon forgotten.","It cost nothing at all.","It was finished within a single year."],"explanation":"末段 ''a model of how nations can work together'' 的转述。"}]'::jsonb, '[{"word":"dam","cn":"水坝"},{"word":"committee","cn":"委员会"},{"word":"relic","cn":"文物;遗迹"}]'::jsonb, 2, 'required2', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Digital Light for the Mogao Caves', 'Near the city of Dunhuang lie the Mogao Caves, a key stop along the ancient Silk Road. For more than a thousand years, travellers from many lands stopped here, and the walls of the caves were covered with beautiful paintings. Today these paintings face a quiet danger: time, light, and crowds of visitors slowly wear them away. To protect them, a team of researchers from China and other countries began an international project in 1994. Instead of touching the fragile walls, they take high-quality digital photographs of every painting. So far, nearly five hundred thousand images have been produced. By sharing these pictures over the Internet, the team hopes to promote interest in China''s history and culture around the world. A museum in America has even made a copy of one cave so that people far away can admire it. In this way, modern technology helps a thousand-year-old treasure reach new eyes without harming the real thing.', 'Cultural Heritage', 157, '[{"q":"What danger do the cave paintings face?","answer":"B","options":["They are being painted over by artists.","They are slowly worn away by time, light and visitors.","They are too bright to look at.","They are kept in a foreign country."],"explanation":"原文 ''time, light, and crowds of visitors slowly wear them away'' 的转述。"},{"q":"How does the team protect the paintings?","answer":"C","options":["By closing the caves to everyone.","By moving the walls to a museum.","By taking digital photos instead of touching the walls.","By repainting them every year."],"explanation":"原文 ''they take high-quality digital photographs… Instead of touching the fragile walls'' 的转述。"},{"q":"Why does the team share the pictures online?","answer":"D","options":["To sell them for money.","To replace the real caves forever.","To stop people from visiting Dunhuang.","To raise interest in Chinese history around the world."],"explanation":"原文 ''hopes to promote interest in China''s history and culture around the world'' 的转述。"}]'::jsonb, '[{"word":"digital","cn":"数码的"},{"word":"image","cn":"图像"},{"word":"promote","cn":"促进;推广"}]'::jsonb, 2, 'required2', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Caring for the Great Wall', 'The Great Wall of China is the largest structure ever made by people, and one of the great wonders of the world. It winds across mountains and deserts for thousands of kilometres, so it is an important heritage site not only for China but for everyone. Yet not every part of the wall is easy to find. Over the long centuries, wind, rain and wild plants have damaged many sections, and some have fallen into ruins. In a few places, weeds growing in the cracks even speed up the wall''s collapse. To care for it, surveyors and archaeologists study the wall to record its true length and condition. Groups of volunteers visit the quieter parts once a month to clear away rubbish and watch for new damage. They hope that more people will join them, for the wall belongs to the whole world. By protecting it now, they can pass this great cultural treasure on to future generations.', 'Cultural Heritage', 158, '[{"q":"Why is the Great Wall important to everyone, not just China?","answer":"A","options":["Because it is the largest human structure and a world wonder.","Because it is easy to walk along.","Because it was built last year.","Because it is only a few metres long."],"explanation":"原文 ''the largest structure ever made… one of the great wonders of the world… for everyone'' 的转述。"},{"q":"What has damaged many parts of the wall?","answer":"B","options":["Too many new buildings.","Weather and wild plants over the centuries.","Tourists buying tickets.","The work of the volunteers."],"explanation":"原文 ''wind, rain and wild plants have damaged many sections'' 的转述。"},{"q":"What do the volunteers hope will happen?","answer":"C","options":["That the wall will be taken down.","That fewer people will care about it.","That more people will help protect the wall.","That the wall will be sold abroad."],"explanation":"原文 ''hope that more people will join them'' 的转述。"}]'::jsonb, '[{"word":"heritage","cn":"遗产"},{"word":"preserve","cn":"保护"},{"word":"professional","cn":"专业的"}]'::jsonb, 2, 'required2', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'When the Old Meets the New', 'Cities need to grow. New roads, new homes and new factories can make people''s lives better. But growth often meets the past head-on. When a new road is planned, an old temple may stand in its way; when a dam is built, ancient relics may end up under water. There comes a time when the old must give way to the new, yet it is not possible to keep everything from the past. Finding the right balance between progress and protection is one of the biggest challenges a society can face. The story of the Aswan Dam shows that the choice need not be simple loss. With careful planning and the help of many hands, a country can build for the future without running over the treasures of the past. The best solutions, people have learned, are the ones that respect both the needs of today and the memory of yesterday.', 'Cultural Heritage', 151, '[{"q":"What problem does the passage mainly discuss?","answer":"D","options":["How to build the tallest factory.","How to stop all cities from growing.","How to make roads cheaper.","How to balance new growth with protecting the past."],"explanation":"原文 ''Finding the right balance between progress and protection'' 的转述。"},{"q":"What does the Aswan Dam story teach, according to the text?","answer":"A","options":["That a country can grow without losing its treasures.","That progress always destroys the past.","That dams should never be built.","That the past is not worth saving."],"explanation":"原文 ''build for the future without running over the treasures of the past'' 的转述。"},{"q":"What are the best solutions, according to the writer?","answer":"B","options":["The cheapest ones.","Those that honour today''s needs while remembering the past.","The fastest ones.","The ones that ignore old buildings."],"explanation":"末句 ''respect both the needs of today and the memory of yesterday'' 的转述。"}]'::jsonb, '[{"word":"balance","cn":"平衡"},{"word":"loss","cn":"损失"},{"word":"process","cn":"过程"}]'::jsonb, 2, 'required2', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'A Summer at Mount Tai', 'Last summer, high school students from seven countries came together at Mount Tai for an international youth camp. Mount Tai is one of the most famous mountains in China, and people have climbed and honoured it for more than three thousand years. On its slopes stand many temples, and thousands of stones are carved with old writing. The students wanted to share this treasure with people their own age, so they decided to create an app about the mountain. Every day they took photos of the temples and the carved stones, and they wrote simple notes to explain each one. In the afternoons, some of them visited nearby middle schools to talk with local teenagers about the value of protecting cultural heritage. One member said that he felt proud to help Mount Tai, just as people had done for thousands of years. By the end of the camp, the young volunteers had not only built an app but also made many new friends.', 'Cultural Heritage', 163, '[{"q":"What did the students decide to create at the camp?","answer":"C","options":["A new road up the mountain.","A large new temple.","An app to introduce the mountain to young people.","A film about their school."],"explanation":"原文 ''decided to create an app about the mountain'' 的转述。"},{"q":"What did some students do in the afternoons?","answer":"D","options":["They climbed to the very top alone.","They sold the photos they had taken.","They rested and did nothing.","They visited local schools to talk about protecting heritage."],"explanation":"原文 ''visited nearby middle schools to talk with local teenagers'' 的转述。"},{"q":"How did one member feel about helping Mount Tai?","answer":"A","options":["Proud, like people before him.","Tired and unwilling.","Bored by the old stones.","Sorry that he had come."],"explanation":"原文 ''felt proud to help Mount Tai'' 的转述。"}]'::jsonb, '[{"word":"creative","cn":"有创造力的"},{"word":"tradition","cn":"传统"},{"word":"heritage","cn":"遗产"}]'::jsonb, 2, 'required2', 'U1');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit) VALUES (10, 'Heritage You Cannot Touch', 'When we think of cultural heritage, we often picture temples, palaces and old relics. But a country''s heritage is much more than the things we can touch. It also includes its traditions, customs and knowledge, such as dances, music, crafts and festivals. This kind of heritage is called intangible cultural heritage, because it lives in what people do rather than in stone or wood. A craft passed from grandmother to granddaughter, a folk song sung at a village festival, a special way of making paper — all of these carry the memory of a people. Yet such traditions can disappear quickly. If the young no longer learn them, they may be lost within a single generation. That is why many countries now record these arts, teach them in schools, and invite young people to take part in festivals. By keeping both the relics we can touch and the traditions we cannot, a culture stays alive and whole.', 'Cultural Heritage', 157, '[{"q":"What is intangible cultural heritage?","answer":"B","options":["Only very old stone buildings.","Heritage that exists in people''s actions rather than in objects.","Modern factories and roads.","Photos kept in a museum."],"explanation":"原文 ''lives in what people do rather than in stone or wood'' 的转述。"},{"q":"Why can such traditions disappear quickly?","answer":"C","options":["Because they are made of weak stone.","Because they cost too much money.","Because young people may stop learning them.","Because they are kept overseas."],"explanation":"原文 ''If the young no longer learn them, they may be lost'' 的转述。"},{"q":"What do many countries do to protect this heritage?","answer":"D","options":["They forbid all festivals.","They sell the old crafts.","They hide them from everyone.","They record the arts and teach them to the young."],"explanation":"原文 ''record these arts, teach them in schools, and invite young people'' 的转述。"}]'::jsonb, '[{"word":"tradition","cn":"传统"},{"word":"disappear","cn":"消失"},{"word":"within","cn":"在……之内"}]'::jsonb, 2, 'required2', 'U1');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U1', 'My First Visit to the Great Wall', 'Last weekend I finally visited the Great Wall with my family. Standing on it, I could hardly believe that people had (1)____ such a huge structure by hand. Our guide told us that it is one of the great (2)____ of the world. As we walked, she pointed to a part that had fallen into (3)____ because of wind and rain. "If we do not (4)____ it," she said, "more of it will be lost forever." She explained that surveyors and archaeologists (5)____ the wall every year to record its true length. A group of (6)____ also come here once a month to clear away rubbish. I felt that protecting such a treasure was truly (7)____ . On the way home, I kept thinking about how each (8)____ of us can help. The wall does not belong only to China; it is a (9)____ site for the whole world. I decided that one day I would (10)____ part in protecting it too.', 162, 2, '[{"q":"1","answer":"A","options":["built","eaten","sold","lost"],"explanation":"had built 建造了。"},{"q":"2","answer":"B","options":["prices","wonders","noises","shops"],"explanation":"wonders of the world 世界奇迹。"},{"q":"3","answer":"C","options":["water","music","ruins","money"],"explanation":"fallen into ruins 成为废墟。"},{"q":"4","answer":"D","options":["forget","sell","leave","protect"],"explanation":"protect it 保护它。"},{"q":"5","answer":"A","options":["study","throw","buy","hide"],"explanation":"study the wall 研究城墙。"},{"q":"6","answer":"B","options":["machines","volunteers","gardens","tickets"],"explanation":"volunteers 志愿者。"},{"q":"7","answer":"C","options":["boring","useless","worthwhile","cheap"],"explanation":"truly worthwhile 真正值得。"},{"q":"8","answer":"D","options":["price","noise","weather","one"],"explanation":"each one of us 我们每一个人。"},{"q":"9","answer":"A","options":["heritage","garden","market","machine"],"explanation":"a heritage site 遗产地。"},{"q":"10","answer":"B","options":["sell","take","lose","hide"],"explanation":"take part in 参与。"}]'::jsonb, 1);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U1', 'A Letter Asking for Help', 'Dear Sir, I am writing on behalf of a small town that needs your (1)____ . Near our town stands an old temple that is more than five hundred years (2)____ . Last month, heavy rain damaged its roof, and we are afraid the whole building may (3)____ . The local people love this temple, but we do not have enough (4)____ to repair it. A few experts have already (5)____ the building and made a clear plan. They believe the temple can still be (6)____ if work begins soon. We are now trying to raise (7)____ from people who care about cultural heritage. Could your organisation (8)____ some money to our effort? Every small gift will make a real (9)____ . We do not want such an important relic to (10)____ forever. Thank you for your kind support. Yours faithfully, the Town Heritage Group.', 145, 2, '[{"q":"1","answer":"C","options":["noise","price","help","weather"],"explanation":"needs your help 需要帮助。"},{"q":"2","answer":"D","options":["high","wide","deep","old"],"explanation":"years old 历史悠久。"},{"q":"3","answer":"A","options":["fall","grow","sing","laugh"],"explanation":"may fall 可能倒塌。"},{"q":"4","answer":"B","options":["songs","money","games","foods"],"explanation":"enough money 足够的钱。"},{"q":"5","answer":"C","options":["eaten","sold","studied","thrown"],"explanation":"studied the building 研究了建筑。"},{"q":"6","answer":"D","options":["lost","broken","sold","saved"],"explanation":"can be saved 能被拯救。"},{"q":"7","answer":"A","options":["funds","noise","weather","prices"],"explanation":"raise funds 筹集资金。"},{"q":"8","answer":"B","options":["forget","give","hide","lose"],"explanation":"give money 捐钱。"},{"q":"9","answer":"C","options":["mistake","noise","difference","price"],"explanation":"make a difference 起作用。"},{"q":"10","answer":"D","options":["grow","sing","laugh","disappear"],"explanation":"disappear forever 永远消失。"}]'::jsonb, 2);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U1', 'A Day as a Museum Volunteer', 'Every Saturday I work as a (1)____ at the city museum. My job is to help visitors understand the old (2)____ that are kept there. Some of them are thousands of years (3)____ , and each one tells a story about the people who made it. In the morning, I (4)____ visitors around the quiet halls and answer their questions. Many children are surprised to learn that one small bowl can (5)____ so much history. I always remind them not to (6)____ the objects, because even a gentle hand can cause (7)____ over time. In the afternoon, I help the staff to clean and (8)____ each item carefully. The work is tiring, but it is also (9)____ , because I feel I am helping to (10)____ our cultural heritage for the future. I hope more young people will join us.', 140, 2, '[{"q":"1","answer":"A","options":["volunteer","machine","price","noise"],"explanation":"a volunteer 志愿者。"},{"q":"2","answer":"B","options":["songs","relics","games","foods"],"explanation":"old relics 古老文物。"},{"q":"3","answer":"C","options":["wide","deep","old","high"],"explanation":"years old 年代久远。"},{"q":"4","answer":"D","options":["sell","eat","throw","show"],"explanation":"show visitors around 带参观。"},{"q":"5","answer":"A","options":["carry","throw","sell","lose"],"explanation":"carry so much history 承载历史。"},{"q":"6","answer":"B","options":["forget","touch","buy","leave"],"explanation":"not to touch 不要触摸。"},{"q":"7","answer":"C","options":["music","money","damage","weather"],"explanation":"cause damage 造成损害。"},{"q":"8","answer":"D","options":["sell","hide","lose","check"],"explanation":"check each item 检查每件。"},{"q":"9","answer":"A","options":["worthwhile","boring","useless","cheap"],"explanation":"worthwhile 值得。"},{"q":"10","answer":"B","options":["break","preserve","sell","lose"],"explanation":"preserve heritage 保护遗产。"}]'::jsonb, 3);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U1', 'Moving a Temple Stone by Stone', 'Saving an ancient temple is harder than most people (1)____ . When rising water threatened the temples on the Nile, engineers could not simply lift a whole building and (2)____ it away. Instead, they had to take it down piece by (3)____ . First, experts gave every stone a number, so that nothing would be (4)____ later. Then workers carefully (5)____ the stones onto trucks and carried them to higher ground. There, following the numbers, they put the temple back (6)____ exactly as before. The whole (7)____ took many years and the help of thousands of people. Fifty countries (8)____ money to make it possible. When the last stone was finally in (9)____ , everyone cheered. It was proof that, with patience and teamwork, even the heaviest treasure can be (10)____ from the water.', 134, 2, '[{"q":"1","answer":"C","options":["eat","sell","think","hide"],"explanation":"than people think 人们以为的。"},{"q":"2","answer":"D","options":["sing","sleep","laugh","carry"],"explanation":"carry it away 搬走。"},{"q":"3","answer":"A","options":["piece","song","price","noise"],"explanation":"piece by piece 一块一块。"},{"q":"4","answer":"B","options":["sold","lost","eaten","sung"],"explanation":"would be lost 丢失。"},{"q":"5","answer":"C","options":["ate","sold","lifted","threw"],"explanation":"lifted the stones 抬起石头。"},{"q":"6","answer":"D","options":["away","down","off","together"],"explanation":"put back together 重新组装。"},{"q":"7","answer":"A","options":["process","price","noise","weather"],"explanation":"the whole process 整个过程。"},{"q":"8","answer":"B","options":["lost","gave","hid","sold"],"explanation":"gave money 捐钱。"},{"q":"9","answer":"C","options":["noise","price","place","music"],"explanation":"in place 安放到位。"},{"q":"10","answer":"D","options":["thrown","sold","lost","saved"],"explanation":"be saved 被拯救。"}]'::jsonb, 4);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U1', 'A Digital Day at Dunhuang', 'My aunt is a researcher (1)____ works on protecting the Mogao Caves. One day she took me to see her job. I had expected to watch people painting, but instead they were taking (2)____ photographs of the walls. "We never (3)____ the paintings," she told me, "because even soft light can harm them." Using special cameras, the team records every (4)____ in great detail. The pictures they take are of very high (5)____ , so people far away can study them too. My aunt said that they (6)____ these images on the Internet to (7)____ interest in China''s history. By the end of the day, I understood that modern (8)____ can protect very old art. The caves have stood for more than a (9)____ years, and thanks to this work, they may be enjoyed for many more. I felt proud that my aunt was helping to (10)____ such a treasure.', 150, 2, '[{"q":"1","answer":"A","options":["who","which","where","when"],"explanation":"researcher who 指人作主语。"},{"q":"2","answer":"B","options":["price","digital","noise","weather"],"explanation":"digital photographs 数码照片。"},{"q":"3","answer":"C","options":["sell","eat","touch","sing"],"explanation":"never touch 从不触碰。"},{"q":"4","answer":"D","options":["song","price","noise","image"],"explanation":"every image 每个图像。"},{"q":"5","answer":"A","options":["quality","noise","price","weather"],"explanation":"high quality 高质量。"},{"q":"6","answer":"B","options":["lose","share","hide","throw"],"explanation":"share on the Internet 在网上分享。"},{"q":"7","answer":"C","options":["forget","lose","promote","break"],"explanation":"promote interest 促进兴趣。"},{"q":"8","answer":"D","options":["food","noise","price","technology"],"explanation":"modern technology 现代技术。"},{"q":"9","answer":"A","options":["thousand","minute","second","metre"],"explanation":"a thousand years 一千年。"},{"q":"10","answer":"B","options":["break","preserve","sell","lose"],"explanation":"preserve 保护。"}]'::jsonb, 5);
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order) VALUES (10, 'required2', 'U1', 'Learning About Living Heritage', 'In class today our teacher gave us a task (1)____ I really enjoyed. She asked us to learn about heritage that you cannot (2)____ with your hands. At first I was confused, because I always thought heritage meant old (3)____ and buildings. But she explained that a country''s customs, dances and (4)____ are also part of its heritage. This kind is called intangible heritage, because it lives in what people (5)____ . My grandmother, for example, knows an old way of making paper (6)____ few young people can do today. The teacher warned that such skills may (7)____ if no one learns them. So she asked each of us to find one (8)____ from our own family and write about it. I chose my grandmother''s paper, and I felt proud to (9)____ such knowledge alive. By the end of the lesson, I understood that heritage is not only about the (10)____ , but also about the people of today.', 159, 2, '[{"q":"1","answer":"C","options":["who","where","that","when"],"explanation":"a task that 指物作宾语。"},{"q":"2","answer":"D","options":["sell","sing","sleep","touch"],"explanation":"cannot touch 摸不到。"},{"q":"3","answer":"A","options":["relics","songs","games","foods"],"explanation":"old relics 古老文物。"},{"q":"4","answer":"B","options":["prices","traditions","noises","machines"],"explanation":"traditions 传统。"},{"q":"5","answer":"C","options":["sell","throw","do","hide"],"explanation":"what people do 人们所做的事。"},{"q":"6","answer":"D","options":["who","where","when","that"],"explanation":"a way that 指物作宾语。"},{"q":"7","answer":"A","options":["disappear","grow","sing","laugh"],"explanation":"may disappear 可能消失。"},{"q":"8","answer":"B","options":["price","tradition","noise","weather"],"explanation":"one tradition 一项传统。"},{"q":"9","answer":"C","options":["sell","lose","keep","throw"],"explanation":"keep it alive 使其延续。"},{"q":"10","answer":"D","options":["food","noise","price","past"],"explanation":"about the past 关于过去。"}]'::jsonb, 6);
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·对话 At the Forbidden City', '必修二 U1 · dialogue', 3, 'Tourist: Excuse me, could you please tell me about this old mirror?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·短文 What Is Cultural Heritage', '必修二 U1 · passage', 2, 'Cultural heritage is what we receive from the past.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·对话 Interview at the Youth Camp', '必修二 U1 · dialogue', 3, 'Reporter: Hello, can you tell me what your camp is doing at Mount Tai?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·短文 Three Ways to Help', '必修二 U1 · passage', 2, 'Here are three simple ways to protect cultural heritage.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·对话 Raising Money for the Temple', '必修二 U1 · dialogue', 3, 'Anna: Our committee needs to raise more money to repair the old temple.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit) VALUES (10, 'U1 听力·短文 Help from the United Nations', '必修二 U1 · passage', 2, 'Sometimes a problem is too big for one country alone.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit) VALUES (10, 'Write a News Report about Protecting Cultural Heritage(写一篇保护文化遗产的新闻报道)', 'Protecting Our Cultural Heritage', '假设你是校英语报记者李华。某团体长期致力于保护本地文化遗产(拍摄老建筑、采访老人、修缮古庙、向学生宣传)。请用英语写一篇约100词的新闻报道,内容包括:① 一句导语,说明谁、做什么、在哪里、为什么;② 主体段落,介绍该团体的具体做法,并引用一句他们的话;③ 简短结尾,总结其意义。注意:适当使用定语从句来介绍人、物、地点或时间。', 'Suppose you are Li Hua, a reporter for the school English newspaper. A local group has worked for years to protect cultural heritage (taking photos of old buildings, interviewing elderly people, repairing old temples, and telling students about them). Write a news report of about 100 words including: 1) a lead sentence telling who, what, where and why; 2) a body explaining what the group does, with one quote; 3) a short ending that sums up its meaning. Use relative clauses to identify people, things, places or times.', '["导语:谁/做什么/在哪里/为什么(Lead sentence)","主体:具体做法 + 一句引用(quote)","结尾:简短总结意义(short summary)","恰当使用定语从句(who/which/that/where/when)介绍人、物、地点、时间"]'::jsonb, 70, 100, 'Wuhan, 8 May 2026. A local group called Protectors of the Past, which is made up of teachers and students, is working hard to protect the city''s cultural heritage. Every weekend, members who love history take photos of old buildings that may soon disappear. They also interview elderly people whose stories help explain the past, and they visit schools where they teach students why heritage matters. "Neither people nor buildings last forever, but our photos can help us remember them," said the group''s leader. Through their patient work, this small group reminds us all that protecting the past is everyone''s duty.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["A local group, which is made up of teachers and students, is working hard to protect the city''s cultural heritage.","Members who love history take photos of old buildings that may soon disappear.","They interview elderly people whose stories help explain the past.","Neither people nor buildings last forever, but our photos can help us remember them."]'::jsonb, '[{"wrong":"The man who he took the photos is a teacher.","correct":"The man who took the photos is a teacher.","note":"who 已作从句主语,不可再加 he。"},{"wrong":"The temple where they repaired is very old.","correct":"The temple that they repaired is very old.","note":"从句缺宾语(repaired ___)用 that/which,不用 where。"},{"wrong":"It is a group makes up of students.","correct":"It is a group made up of students.","note":"be made up of 固定搭配;此处用过去分词作定语。"}]'::jsonb, '【新闻报道结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content) VALUES (10, 'required2', 'U1', '{"title":"限制性定语从句·关系词速查(who/whom/which/that·whose·where/when/why)","intro":"先看先行词指人还是指物,再看从句缺什么成分。缺主语/宾语→用关系代词(who/whom/which/that);不缺主宾、只缺状语→用关系副词(where/when/why)或「介词+which/whom」;表所属→whose。","table":{"headers":["关系词","用法 / 例句"],"rows":[["who","指人、从句缺主语:the guide who knows the city"],["whom","指人、从句缺宾语或介词后:the man whom we met / to whom I spoke"],["which / that","指物、从句缺主宾:the temple which/that was moved"],["whose","表所属(谁的):the writer whose book won a prize"],["where / when / why","从句缺地点/时间/原因状语:the place where… / the day when… / the reason why…"],["介词+which/whom","从句不缺主宾、更正式:in which / by which / to whom"]]},"specialRules":[{"rule":"从句缺主语/宾语 → 关系代词(who/whom/which/that)","mark":"the relics that we saved(缺宾语→that)"},{"rule":"从句不缺主宾、只缺状语 → 关系副词或介词+which","mark":"the place where = in which"},{"rule":"介词后只能用 which 或 whom,不可用 that","mark":"through which √ / through that ×"},{"rule":"whose = 谁的,引导表所属的从句","mark":"the engineer whose team moved the temples"}],"why":["关系副词(where/when/why)= 介词+which,在从句里作状语,所以主语、宾语都齐;一旦从句缺了主语或宾语,就必须换成关系代词 who/whom/which/that。"],"gaokaoPoints":["判断口诀:先行词指人/指物 + 从句缺主宾还是缺状语;语法填空高频。","易错:先行词是地点/时间但从句缺宾语时,用 that/which 而非 where/when(the place that I visited)。","介词提前时,指物用 which、指人用 whom(in which / to whom),不用 that。"],"examVsReal":[{"exam":"the door through which you can leave（考试/书面）","real":"the door you can leave through","note":"口语常省略关系词、把介词放句末"},{"exam":"the man to whom I spoke（正式）","real":"the man I spoke to / the man who I spoke to","note":"口语里常省略 whom 或用 who,介词移到句末"}]}'::jsonb);
